<?php
require $argv[1];spl_autoload_register(function($c){$p='OmegaGuardian\\ProfilerShield\\';if(strpos($c,$p)===0)require __DIR__.'/../src/'.str_replace('\\','/',substr($c,strlen($p))).'.php';},true,true);
use OmegaGuardian\ProfilerShield\Storage\FileStore;
use OmegaGuardian\ProfilerShield\Security\{Settings,Sessions,Audit,Totp,Accounts,Policy,DiagnosticAccess};
use Symfony\Component\HttpFoundation\{Request,Response};
$key=bin2hex(random_bytes(32));$_SERVER['GUARDIAN_ENCRYPTION_KEY']=$key;$dir=sys_get_temp_dir().'/guardian-state-'.bin2hex(random_bytes(6));$s=new FileStore($dir);$s->initialize();$cfg=new Settings($s);$sessions=new Sessions($s,$cfg);$audit=new Audit($s);$n=0;$bad=[];
function ok($c,$m){global $n,$bad;$n++;if(!$c)$bad[]=$m;}
foreach(['minimal','standard','advanced'] as $level){$cfg->set(['audit_level'=>$level]);$s->change('audit',function(){return [];});$audit->record('login_success','test',['password'=>'secret','reason'=>'acceptable']);$audit->record('emergency_granted','test',[],true);$entries=$s->read('audit');ok(count($entries)===($level==='minimal'?1:2),'audit level '.$level);ok(strpos(json_encode($entries),'secret')===false,'audit strips secrets');ok(count($s->read('alerts'))>0,'emergency queue durable');}
$cfg->set(['audit_retention_days'=>1]);$s->change('audit',function($a){$a[0]['at']=gmdate('c',time()-3*86400);return $a;});$audit->record('settings_updated');foreach($s->read('audit') as $entry)ok(strtotime($entry['at'])>=time()-86400,'audit retention');
foreach([1,14,720] as $days){$cfg->set(['remember_days'=>$days]);$r=new Response();$before=time();$sessions->rememberDevice('test',$r);$c=$r->headers->getCookies()[0];ok(abs($c->getExpiresTime()-($before+$days*86400))<3,'remember cookie duration');$request=Request::create('https://localhost/','GET',[],[Sessions::DEVICE_COOKIE=>$c->getValue()]);ok($sessions->recognized($request),'remember recognized');ok(strpos(file_get_contents($dir.'/devices.json'),$c->getValue())===false,'device token not plaintext');$s->change('devices',function($a){foreach($a as &$v)$v['expires']=time()-1;return $a;});ok(!$sessions->recognized($request),'remember expiry');}
$cfg->set(['idle_minutes'=>1]);$r=new Response();$sessions->begin('test',$r);$cookie=$r->headers->getCookies()[0];$req=Request::create('https://localhost/','GET',[],[Sessions::COOKIE=>$cookie->getValue()]);$id=hash('sha256',$cookie->getValue());$s->change('sessions',function($a)use($id){$a[$id]['last']=time()-61;return $a;});ok($sessions->current($req)===null,'idle expiry');
$totp=new Totp();$secret='GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ';ok($totp->verify($secret,'287082',59),'RFC6238');foreach(['','12345','1234567','abcdef','１２３４５６',null,[]] as $code)ok(!$totp->verify($secret,$code,59),'bad OTP');$encrypted=$totp->encrypt($secret);ok($totp->decrypt($encrypted)===$secret,'TOTP round trip');try{$totp->decrypt(substr($encrypted,0,-4).'AAAA');ok(false,'TOTP tamper');}catch(RuntimeException $e){ok(true,'TOTP tamper');}
$accounts=new Accounts($s);$access=new DiagnosticAccess($sessions,$accounts,new Policy($cfg,$s));ok(!$access->allowed(Request::create('/_profiler/')),'anonymous fail closed');foreach(['../settings','/tmp/x','UPPER',str_repeat('a',50)] as $name){try{$s->read($name);ok(false,'collection name');}catch(InvalidArgumentException $e){ok(true,'collection name');}}
$s->change('settings',function($a){return $a;});$_SERVER['GUARDIAN_ENCRYPTION_KEY']=bin2hex(random_bytes(32));try{$s->read('settings');ok(false,'wrong encryption key');}catch(RuntimeException $e){ok(true,'wrong encryption key');}$_SERVER['GUARDIAN_ENCRYPTION_KEY']=$key;
foreach(glob($dir.'/*') as $f)unlink($f);@unlink($dir.'/.htaccess');rmdir($dir);echo json_encode(['assertions'=>$n,'failures'=>$bad],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE),"\n";exit($bad?1:0);
